#!/usr/bin/env bash
# Regenerates generated/: Intel's intel-tee-quote-verification-sys crate at the pinned DCAP
# commit, with patches/series applied, plus the licenses of everything it compiles in.
#
#   ./update.sh               regenerate generated/
#   ./update.sh --keep DIR    also leave the patched crate in DIR as a git repository, with
#                             Intel's crate as the first commit and one commit per patch; edit
#                             there, then export the series again with
#                             git -C DIR format-patch -N --no-signature --zero-commit \
#                               -o "$PWD/patches" HEAD~<number of patches>
#
# CI runs it and fails if generated/ changes, so generated/ is always exactly Intel's crate
# plus the patches. Needs git and network access to GitHub.
set -euo pipefail

# intel/confidential-computing.tee.dcap: the commit Cargo.lock resolves
# intel-tee-quote-verification-rs 0.4.0 to, which Trustee's TDX verifier pins by tag. Its
# CRATE_PATH is the crate this one replaces, as published to crates.io as 0.3.0. The patched
# build.rs compiles the C sources of the same commit; this script checks the two agree.
DCAP_URL=https://github.com/intel/confidential-computing.tee.dcap.git
DCAP_REV=ecdb68e9854b20d5f6a27cd874f7e89e977e9ca1 # DCAP_1.27
# intel/confidential-computing.sgx.sdk at the commit intel/linux-sgx tag sgx_2.30 pins, for
# the license of the SGX headers build.rs compiles against. Kept in step with build.rs.
SGX_SDK_URL=https://github.com/intel/confidential-computing.sgx.sdk.git
SGX_SDK_REV=73ae8ba0140f9295ef62245897c578c76c289341 # SGX SDK 2.30, via linux-sgx sgx_2.30
CRATE_PATH=QuoteVerification/dcap_quoteverify/sgx-dcap-quoteverify-sys

here=$(cd "$(dirname "$0")" && pwd)
keep=
if [ "${1-}" = --keep ]; then
  keep=${2:?--keep needs a directory}
fi

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

fetch() { # <url> <rev> <dir> [submodule...]
  local url=$1 rev=$2 dir=$3
  shift 3
  git init -q "$dir"
  # A named remote: DCAP's submodule URLs are relative to it.
  git -C "$dir" remote add origin "$url"
  git -C "$dir" fetch -q --depth 1 --filter=blob:none origin "$rev"
  git -C "$dir" -c advice.detachedHead=false checkout -q FETCH_HEAD
  if [ $# -gt 0 ]; then
    git -C "$dir" submodule update -q --init --depth 1 -- "$@"
  fi
}

fetch "$DCAP_URL" "$DCAP_REV" "$tmp/dcap" QuoteVerification/QVL external/jwt-cpp
fetch "$SGX_SDK_URL" "$SGX_SDK_REV" "$tmp/sgx-sdk"

# Apply the series to Intel's crate in one go. `git am` rather than `git apply` only so that
# --keep leaves one commit per patch to edit and export again.
work=$tmp/crate
cp -R "$tmp/dcap/$CRATE_PATH" "$work"
patches=()
while IFS= read -r patch; do
  case $patch in "" | "#"*) continue ;; esac
  patches+=("$here/patches/$patch")
done <"$here/patches/series"
git -C "$work" init -q
git -C "$work" add -A
git -C "$work" -c user.name=update.sh -c user.email=update.sh@invalid \
  commit -q -m "intel-tee-quote-verification-sys from DCAP $DCAP_REV"
git -C "$work" -c user.name=update.sh -c user.email=update.sh@invalid am -q "${patches[@]}"

grep -q "rev: \"$DCAP_REV\"" "$work/build.rs" ||
  { echo "update.sh: the patched build.rs does not pin DCAP $DCAP_REV" >&2; exit 1; }
grep -q "rev: \"$SGX_SDK_REV\"" "$work/build.rs" ||
  { echo "update.sh: the patched build.rs does not pin the SGX SDK at $SGX_SDK_REV" >&2; exit 1; }

if [ -n "$keep" ]; then
  rm -rf "$keep"
  cp -R "$work" "$keep"
fi

# Notices for everything build.rs compiles into the library: Intel's DCAP, QVL and SGX SDK
# headers (BSD-3-Clause), and RapidJSON and jwt-cpp (MIT).
rm -rf "$work/.git"
mkdir "$work/licenses"
cp "$tmp/dcap/License.txt" "$work/licenses/intel-dcap.txt"
cp "$tmp/dcap/QuoteVerification/QVL/License.txt" "$work/licenses/intel-qvl.txt"
cp "$tmp/dcap/QuoteVerification/QVL/ThirdPartyLicenses.txt" "$work/licenses/intel-qvl-third-party.txt"
cp "$tmp/dcap/external/jwt-cpp/LICENSE" "$work/licenses/jwt-cpp.txt"
cp "$tmp/sgx-sdk/License.txt" "$work/licenses/intel-sgx-sdk.txt"

cat >"$work/DO-NOT-EDIT.md" <<EOF
Generated by ../update.sh from Intel's \`$CRATE_PATH\` at
$DCAP_URL $DCAP_REV, with ../patches/series applied. Edit the patches, not this directory.
EOF

rm -rf "$here/generated"
cp -R "$work" "$here/generated"
echo "generated/ updated"
